cas_complets.code:
flowchart TD
    A([Pas d'accès à Internet]) --> B{Les autres appareils ont-ils Internet ?}
    B -->|Oui| C[Problème sur ton appareil]
    B -->|Non| D[Problème de box ou d'opérateur]
    C --> C1{Wi-Fi activé ?}
    C1 -->|Non| C2[Activer le Wi-Fi] --> E([Résolu])
    C1 -->|Oui| C3[Oublier le réseau et se reconnecter] --> E
    D --> D1[Redémarrer la box] --> D2{Voyant Internet allumé ?}
    D2 -->|Oui| E
    D2 -->|Non| D3([Appeler l'opérateur])

flowchart LR
    S1@{ shape: cyl, label: "CRM" }
    S2@{ shape: docs, label: "Fichiers CSV" }
    S3@{ shape: cloud, label: "API météo" }
    T@{ shape: rect, label: "Nettoyage et fusion" }
    Q@{ shape: diam, label: "Qualité OK ?" }
    DW@{ shape: cyl, label: "Entrepôt de données" }
    R@{ shape: doc, label: "Rapport d'erreurs" }
    DB@{ shape: curv-trap, label: "Tableau de bord" }
    S1 & S2 & S3 --> T --> Q
    Q -->|Oui| DW
    Q -->|Non| R
    DW e1@--> DB
    e1@{ animate: true }
